use gpui::{Rgba, Styled, Svg, px, svg};

pub fn lucide_icon(svg_bytes: &'static [u8], size_px: f32, color: Rgba) -> Svg {
    svg()
        .data(svg_bytes)
        .size(px(size_px))
        .flex_none()
        .text_color(color)
}

